let runtimeUnloading=false;
function runtimeNetwork(){
  const network=report.runtime.network,filter={urls:['http://*/*','https://*/*']},engine=new URL('lijiang-m8/engine.html',runtimeBase);
  window.webContents.session.webRequest.onBeforeRequest(filter,(details,callback)=>{
    const u=new URL(details.url),entry={url:details.url,type:details.resourceType,api:report.runtime.activeApi,time:Date.now()};network.requests.push(entry);
    const forbidden=u.origin!==runtimeBase.origin&&(isLoopback(u.hostname)||['8796','8797','8798','8799'].includes(u.port));
    const allowedEngine=details.resourceType==='subFrame'&&report.runtime.activeApi==='lijiangRaster'&&u.origin===engine.origin&&u.pathname===engine.pathname&&u.searchParams.get('fieldsonly')==='1';
    if(forbidden){network.forbidden.push(entry);fatal='Runtime requested a forbidden local service: '+details.url;callback({cancel:true});}
    else if(details.resourceType==='subFrame'&&!allowedEngine){report.blockedSubframes.push(entry);fatal='Runtime requested an unexpected subframe: '+details.url;callback({cancel:true});}
    else{if(allowedEngine)network.allowedSubframes.push(entry);callback({});}
  });
  window.webContents.session.webRequest.onCompleted(filter,d=>{if(d.statusCode>=400){const failure={url:d.url,type:d.resourceType,status:d.statusCode,api:report.runtime.activeApi};network.failures.push(failure);fatal='Runtime HTTP failure '+d.statusCode+': '+d.url;}});
  window.webContents.session.webRequest.onErrorOccurred(filter,d=>{const failure={url:d.url,type:d.resourceType,error:d.error,api:report.runtime.activeApi,expectedUnload:runtimeUnloading&&d.error==='net::ERR_ABORTED'};network.failures.push(failure);if(!failure.expectedUnload)fatal='Runtime network failure '+d.error+': '+d.url;});
}
async function runtimeCall(code,timeout=45000){let timer;try{return await Promise.race([call(code),new Promise((_,reject)=>timer=setTimeout(()=>reject(Error('Runtime page call timed out')),timeout))]);}finally{clearTimeout(timer);}}
