async function runtimeClick(selector){const result=await runtimeCall(`(()=>{const b=document.querySelector(${JSON.stringify(selector)}),r=b?.getBoundingClientRect();if(!b||b.disabled||!r?.width||!r?.height||getComputedStyle(b).visibility==='hidden')throw Error('Enabled visible control missing: '+${JSON.stringify(selector)});b.click();return{selector:${JSON.stringify(selector)},text:b.textContent.trim()};})()`);report.runtime.actions.push(result);return result;}
