async function runtimeShot(api,name){const state=await runtimeState(api);assert(state?.ready&&state.frames>=3&&!state.error&&!state.errors?.length,'Screenshot runtime is not healthy');await runtimeCall('document.fonts.ready.then(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))))');const image=await window.webContents.capturePage(),bytes=image.toPNG(),file=path.join(output,name+'.png');assert(!image.isEmpty(),'Runtime screenshot is empty');fs.writeFileSync(file,bytes);const entry={name,path:file,sha256:sha(bytes),size:image.getSize(),state:runtimeSave(name,state)};report.screenshots.push(entry);progress('runtime-screenshot-'+name);return entry;}
async function runtimeDispose(api,bestEffort=false){if(!window||window.isDestroyed())return;runtimeUnloading=true;let timer,error=null,state;try{assert(!window.isVisible()&&!window.isFocused(),'Runtime cleanup window must stay hidden');state=await Promise.race([window.webContents.executeJavaScript(`(async()=>{const a=window[${JSON.stringify(api)}];if(!a)return null;await a.dispose?.();return a.getState?.()||null;})()`,false),new Promise((_,reject)=>timer=setTimeout(()=>reject(Error('Runtime dispose timed out')),30000))]);if(!bestEffort)assert(state&&state.ready===false&&(state.disposed===true||state.phase==='disposed'),'Runtime dispose did not release the scene');}catch(e){error=String(e.message||e);}finally{clearTimeout(timer);try{await window.loadURL('about:blank');}catch(e){error=error||String(e.message||e);}report.runtime.disposals.push({api,bestEffort,error,state:state?runtimeSave(api+'-disposed',state):null,url:window.webContents.getURL()});report.runtime.activeApi=null;runtimeUnloading=false;}if(error&&!bestEffort)throw Error(error);}
